param(
    [string]$ProjectRoot = "C:\Users\arauj\grafica-flash"
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

try {
    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
    $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
} catch {}

$ExpectedBranch = "fix/unify-payment-flows-phase-1"
$BackupRoot = Join-Path $ProjectRoot (".orcaly-backups\fase5-founders-" + (Get-Date -Format "yyyyMMdd-HHmmss"))

$GeneratedFiles = @{
    "supabase/migrations/20260812003227_founder_invite_sales_integration_v1.sql" = ""
    "lib/founder-program.ts" = ""
    "app/api/admin/founders/route.ts" = ""
    "components/admin/FounderInvitesClient.tsx" = ""
    "app/admin/fundadores/page.tsx" = ""
}

$ExpectedSha = @{
    "supabase/migrations/20260812003227_founder_invite_sales_integration_v1.sql" = "80A2B4D220469105410135380CEA66BD099BB88818BB85495AC40F9271793DFC"
    "lib/founder-program.ts" = "42DC6F5E0384198973F48101F5E36CC538427A810E6AA07AA6529BA0C1AACC8D"
    "app/api/admin/founders/route.ts" = "339B6B3A0A640AB3524BC2BE70218BA9790952B16A61C8E8242D35FCDE16BF67"
    "components/admin/FounderInvitesClient.tsx" = "52DD3CA585DAD0171520CA779167B9613DDF087555D296AD49A7F8AD9C42F4A3"
    "app/admin/fundadores/page.tsx" = "FE745D75A015D25620B722618999FB0B411EEF749D1F0944BB50B18876ED4109"
}

$PatchBefore = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
)
$PatchAfter = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
)

$Changed = New-Object System.Collections.Generic.List[string]
$Backups = @{}

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function FullPath([string]$Relative) {
    return Join-Path $ProjectRoot ($Relative -replace "/", "\")
}

function NormalizeNewlines([string]$Value) {
    if ($null -eq $Value) { return "" }
    return $Value.Replace("`r`n", "`n").Replace("`r", "`n")
}

function Backup([string]$Relative) {
    $source = FullPath $Relative

    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) {
        return
    }

    $destination = Join-Path $BackupRoot ($Relative -replace "/", "\")
    [IO.Directory]::CreateDirectory((Split-Path -Parent $destination)) | Out-Null
    Copy-Item -LiteralPath $source -Destination $destination -Force
    $Backups[$Relative] = $destination
}

function MarkChanged([string]$Relative) {
    if (-not $Changed.Contains($Relative)) {
        $Changed.Add($Relative)
    }
}

function WriteBytesWithRetry([string]$Relative, [byte[]]$Bytes) {
    $path = FullPath $Relative
    $directory = Split-Path -Parent $path
    [IO.Directory]::CreateDirectory($directory) | Out-Null

    $temp = Join-Path $directory (
        "." +
        [IO.Path]::GetFileName($path) +
        ".orcaly-fase5-" +
        [Guid]::NewGuid().ToString("N") +
        ".tmp"
    )

    try {
        [IO.File]::WriteAllBytes($temp, $Bytes)
        $written = $false
        $lastError = $null

        for ($attempt = 1; $attempt -le 8; $attempt++) {
            try {
                if (Test-Path -LiteralPath $path -PathType Leaf) {
                    [IO.File]::Copy($temp, $path, $true)
                }
                else {
                    [IO.File]::Move($temp, $path)
                }

                $written = $true
                break
            }
            catch {
                $lastError = $_.Exception
                [GC]::Collect()
                [GC]::WaitForPendingFinalizers()
                Start-Sleep -Milliseconds (250 * $attempt)
            }
        }

        if (-not $written) {
            throw (
                "Windows manteve o arquivo bloqueado: " +
                $Relative +
                ". Feche npm run dev/VS Code e tente novamente. " +
                $(if ($lastError) { $lastError.Message } else { "" })
            )
        }
    }
    finally {
        Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
    }
}

function WriteGenerated([string]$Relative) {
    $path = FullPath $Relative

    if (Test-Path -LiteralPath $path -PathType Leaf) {
        $actual = (Get-FileHash $path -Algorithm SHA256).Hash.ToUpperInvariant()

        if ($actual -eq $ExpectedSha[$Relative]) {
            Ok ($Relative + " ja corresponde a FASE 5.")
            return
        }

        throw ($Relative + " ja existe com conteudo diferente.")
    }

    $bytes = [Convert]::FromBase64String($GeneratedFiles[$Relative])
    WriteBytesWithRetry $Relative $bytes

    $actual = (Get-FileHash (FullPath $Relative) -Algorithm SHA256).Hash.ToUpperInvariant()
    if ($actual -ne $ExpectedSha[$Relative]) {
        throw ("SHA256 inesperado depois de gravar " + $Relative)
    }

    MarkChanged $Relative
    Ok ($Relative + " criado.")
}

function WriteText([string]$Relative, [string]$Text) {
    $bytes = [Text.Encoding]::UTF8.GetBytes((NormalizeNewlines $Text))
    WriteBytesWithRetry $Relative $bytes
}

function Rollback {
    [array]$items = @($Changed)
    [Array]::Reverse($items)

    foreach ($relative in $items) {
        if ($Backups.ContainsKey($relative)) {
            Copy-Item -LiteralPath $Backups[$relative] -Destination (FullPath $relative) -Force
            Warn ("Restaurado: " + $relative)
        }
        else {
            Remove-Item -LiteralPath (FullPath $relative) -Force -ErrorAction SilentlyContinue
            Warn ("Removido: " + $relative)
        }
    }
}

try {
    Write-Host ""
    Write-Host "ORCALY - FASE 5 V2 - CONVITES CLIENTES FUNDADORES" -ForegroundColor Cyan
    Write-Host "#00 tecnico + #01-#10 reais + integracao CRM." -ForegroundColor DarkCyan

    if (-not (Test-Path -LiteralPath (FullPath "package.json") -PathType Leaf)) {
        throw "Repositorio Orcaly nao encontrado."
    }

    Set-Location $ProjectRoot

    $branch = ([string]((& git branch --show-current) | Select-Object -First 1)).Trim()
    if ($branch -ne $ExpectedBranch) {
        throw ("Branch atual: " + $branch + ". Esperada: " + $ExpectedBranch)
    }

    Step "Validando FASES 2 e 4 locais"

    $platformPath = FullPath "lib/platform-admin.ts"
    $prospectingLibPath = FullPath "lib/prospecting.ts"
    $prospectingApiPath = FullPath "app/api/admin/prospecting/route.ts"
    $prospectingClientRelative = "components/admin/ProspectingCrmClient.tsx"
    $prospectingClientPath = FullPath $prospectingClientRelative

    foreach ($path in @(
        $platformPath,
        $prospectingLibPath,
        $prospectingApiPath,
        $prospectingClientPath
    )) {
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            throw (
                "FASE 4 local nao esta concluida. Arquivo ausente: " +
                $path
            )
        }
    }

    $platform = NormalizeNewlines ([IO.File]::ReadAllText($platformPath))
    foreach ($anchor in @(
        "'founders.view_own'",
        "'founders.view_all'",
        "'founders.create_invite'",
        "'founders.resend_invite'",
        "'founders.revoke_pending'"
    )) {
        if (-not $platform.Contains($anchor)) {
            throw ("FASE 2 incompleta. Permissao ausente: " + $anchor)
        }
        Ok ("Permissao confirmada: " + $anchor)
    }

    $prospectingApi = NormalizeNewlines ([IO.File]::ReadAllText($prospectingApiPath))
    if (-not $prospectingApi.Contains("create_or_claim_sales_prospect")) {
        throw "FASE 4 local nao esta concluida: API de Prospecção ausente."
    }

    $prospectingClient = NormalizeNewlines ([IO.File]::ReadAllText($prospectingClientPath))
    $beforeNormalized = NormalizeNewlines $PatchBefore
    $afterNormalized = NormalizeNewlines $PatchAfter

    if (
        -not $prospectingClient.Contains($beforeNormalized) -and
        -not $prospectingClient.Contains($afterNormalized)
    ) {
        throw (
            "ProspectingCrmClient.tsx mudou desde a FASE 4 auditada. " +
            "Nao vou sobrescrever esse trecho."
        )
    }

    Ok "FASE 4 local reconhecida."

    Step "Sincronizando migration ja aplicada no Supabase"

    WriteGenerated "supabase/migrations/20260812003227_founder_invite_sales_integration_v1.sql"

    Step "Criando backend e tela Founder"

    WriteGenerated "lib/founder-program.ts"
    WriteGenerated "app/api/admin/founders/route.ts"
    WriteGenerated "components/admin/FounderInvitesClient.tsx"
    WriteGenerated "app/admin/fundadores/page.tsx"

    Step "Ligando CRM ao Programa Founder"

    $prospectingClient = NormalizeNewlines ([IO.File]::ReadAllText($prospectingClientPath))

    if ($prospectingClient.Contains($beforeNormalized)) {
        Backup $prospectingClientRelative
        $prospectingClient = $prospectingClient.Replace(
            $beforeNormalized,
            $afterNormalized
        )
        WriteText $prospectingClientRelative $prospectingClient
        MarkChanged $prospectingClientRelative
        Ok "CRM agora abre /admin/fundadores para o prospect selecionado."
    }
    else {
        Ok "Integracao CRM -> Founder ja estava aplicada."
    }

    Step "Validando contrato de seguranca"

    $api = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "app/api/admin/founders/route.ts")))
    $lib = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "lib/founder-program.ts")))
    $client = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "components/admin/FounderInvitesClient.tsx")))
    $migration = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "supabase/migrations/20260812003227_founder_invite_sales_integration_v1.sql")))

    function AssertCheck([bool]$Passed, [string]$Name) {
        if (-not $Passed) {
            throw ("Validacao falhou: " + $Name)
        }
        Ok $Name
    }

    AssertCheck ($api.Contains("randomBytes(32)")) "Token criptografico gerado server-side"
    AssertCheck ($api.Contains("createHash('sha256')")) "Somente hash enviado ao banco"
    AssertCheck (-not $api.Contains("NEXT_PUBLIC_SUPABASE_SERVICE")) "Service role nao exposta ao cliente"
    AssertCheck ($api.Contains("'founders.view_own'")) "Consulta exige permissao Founder"
    AssertCheck ($api.Contains("'founders.view_all'")) "Owner possui visao global"
    AssertCheck ($api.Contains("'founders.create_invite'")) "Criacao exige permissao"
    AssertCheck ($api.Contains("requireOfficialPlatformOwner")) "#00 exige Owner oficial"
    AssertCheck ($api.Contains("create_founder_invite_for_sales_lead")) "Criacao real usa RPC atomica"
    AssertCheck ($api.Contains("rotate_founder_invite_token")) "Rotacao usa RPC atomica"
    AssertCheck ($api.Contains("revoke_founder_invite")) "Revogacao usa RPC atomica"
    AssertCheck ($migration.Contains("pg_advisory_xact_lock")) "Alocacao #01-#10 serializada no banco"
    AssertCheck ($migration.Contains("founder_invites_live_sales_lead_uq")) "Um convite live por prospect"
    AssertCheck ($migration.Contains("founder_invites_live_email_uq")) "Um convite live por email"
    AssertCheck ($migration.Contains("FOUNDER_TEST_OWNER_ONLY")) "#00 protegido no banco"
    AssertCheck ($lib.Contains("founderPriceCents: 3490")) "Preco Basico Founder"
    AssertCheck ($lib.Contains("founderPriceCents: 6990")) "Preco Profissional Founder"
    AssertCheck ($lib.Contains("founderPriceCents: 9990")) "Preco Premium Founder"
    AssertCheck ($client.Contains("A ativação pública do cliente entra na FASE 6")) "UI nao finge que ativacao ja existe"

    Step "git diff --check"

    $phase5Files = @(
        "supabase/migrations/20260812003227_founder_invite_sales_integration_v1.sql",
        "lib/founder-program.ts",
        "app/api/admin/founders/route.ts",
        "components/admin/FounderInvitesClient.tsx",
        "app/admin/fundadores/page.tsx",
        $prospectingClientRelative
    )

    & git --no-pager diff --check -- $phase5Files
    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check falhou."
    }
    Ok "Whitespace validado."

    Step "Pre-validando erros encontrados na V1"

    $founderApiCheck = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "app/api/admin/founders/route.ts")))
    $founderClientCheck = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "components/admin/FounderInvitesClient.tsx")))

    AssertCheck (-not $founderApiCheck.Contains("type FounderPlanKey")) "API sem import FounderPlanKey inutilizado"
    AssertCheck (-not $founderClientCheck.Contains("const load = useCallback(async () => {`n    setLoading(true)")) "Load inicial sem setLoading sincrono"
    AssertCheck ($founderClientCheck.Contains("onClick={() => {`n                  setLoading(true)`n                  void load()")) "Loading manual movido para evento de Atualizar"

    Step "ESLint direcionado"

    & npx.cmd eslint `
        "lib/founder-program.ts" `
        "app/api/admin/founders/route.ts" `
        "components/admin/FounderInvitesClient.tsx" `
        "app/admin/fundadores/page.tsx" `
        $prospectingClientRelative

    if ($LASTEXITCODE -ne 0) {
        throw "ESLint direcionado da FASE 5 falhou."
    }
    Ok "ESLint direcionado passou."

    Step "Build completo"

    & npm.cmd run build
    if ($LASTEXITCODE -ne 0) {
        throw "Build final falhou."
    }
    Ok "Build final passou."

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " FASE 5 APLICADA E VALIDADA LOCALMENTE" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Implementado:"
    Write-Host " - CRM -> convite Founder real"
    Write-Host " - #01-#10 com alocacao atomica"
    Write-Host " - #00 tecnico somente Owner"
    Write-Host " - Precos derivados no banco"
    Write-Host " - Token plaintext nunca persistido"
    Write-Host " - Rotacao mata o link anterior"
    Write-Host " - Revogacao devolve prospect para demonstracao"
    Write-Host " - Expiracao automatica quando a tela e consultada"
    Write-Host ""
    Write-Host "A ativacao publica entra na FASE 6." -ForegroundColor Yellow
    Write-Host "Nenhum commit, push ou deploy foi executado." -ForegroundColor Cyan
}
catch {
    Write-Host ""
    Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red

    if ($Changed.Count -gt 0) {
        Warn "Executando rollback dos arquivos alterados."
        Rollback
    }

    Write-Host ("Backup: " + $BackupRoot) -ForegroundColor Yellow
    exit 1
}
